import sqlite3,sys
try:
    c=sqlite3.connect(sys.argv[1]);cur=c.cursor()
    cur.execute("select id from pairs where id like 'relay-watch%'")
    rows=cur.fetchall()
    if rows: print(sys.argv[1], [r[0] for r in rows])
except Exception as e: pass
PY
); [ -n "$hit" ] && echo "$hit"; done

